`#include <stdexcept>
#include <string>
#include <utility>

class User {
private:
    std::string id;
    std::string email;
public:
    User(std::string userId, std::string userEmail)
        : id(std::move(userId)), email(std::move(userEmail)) {
        if (id.empty() || email.empty()) {
            throw std::invalid_argument("id and email are required");
        }
    }
};` The object cannot be successfully constructed without the required values.

